"use strict";(globalThis.webpackChunkaarati_sangrah=globalThis.webpackChunkaarati_sangrah||[]).push([[68938],{71961(n,a,e){e.r(a),e.d(a,{assets:()=>d,contentTitle:()=>c,default:()=>l,frontMatter:()=>s,metadata:()=>t,toc:()=>h});const t=JSON.parse('{"id":"katha/adityaranubai","title":"\u0906\u0926\u093f\u0924\u094d\u092f\u0930\u093e\u0923\u0942\u092c\u093e\u0908\u091a\u0940 (\u092a\u094c\u0937 \u0930\u0935\u0940\u0935\u093e\u0930\u091a\u0940) \u0915\u0939\u093e\u0923\u0940","description":"\u0910\u0915\u093e \u0906\u0926\u093f\u0924\u094d\u092f\u0930\u093e\u0923\u0942\u092c\u093e\u0908 \u0924\u0941\u092e\u091a\u0940 \u0915\u0939\u093e\u0923\u0940. \u0906\u091f\u092a\u093e\u091f \u0928\u0917\u0930 \u0939\u094b\u0924\u0902. \u0924\u094d\u092f\u093e \u0928\u0917\u0930\u093e\u0924 \u090f\u0915 \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u0939\u094b\u0924\u093e. \u0924\u094b \u0928\u093f\u0924\u094d\u092f \u0938\u092e\u093f\u0927\u093e, \u092b\u0941\u0932\u0902, \u0926\u0942\u0930\u094d\u0935\u093e, \u0906\u0923\u093e\u092f\u0932\u093e \u0930\u093e\u0928\u093e\u0902\u0924 \u091c\u093e\u0924 \u0905\u0938\u0947. \u0924\u093f\u0925\u0902 \u0928\u093e\u0917\u0915\u0928\u094d\u092f\u093e \u0926\u0947\u0935\u0915\u0928\u094d\u092f\u093e \u0935\u0938\u093e \u0935\u0938\u0924 \u0939\u094b\u0924\u094d\u092f\u093e. \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928\u0902 \u0935\u093f\u091a\u093e\u0930\u0932\u0902, \\"\u0915\u093e\u092f \u0917 \u092c\u093e\u092f\u093e\u0902\u0928\u094b\u0902, \u0915\u0938\u0932\u093e \u0935\u0938\u093e \u0935\u0938\u0924\u093e\u0902? \u0924\u094b \u092e\u0932\u093e \u0938\u093e\u0902\u0917\u093e.\\" \\" \u0924\u0941\u0932\u093e \u0930\u0947 \u0935\u0938\u093e \u0915\u0936\u093e\u0932\u093e \u0939\u0935\u093e? \u0909\u0924\u0936\u0940\u0932, \u092e\u093e\u0924\u0936\u0940\u0932, \u0918\u0947\u0924\u0932\u093e \u0935\u0938\u093e \u091f\u093e\u0915\u0942\u0928 \u0926\u0947\u0936\u0940\u0932.\\" \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u092e\u094d\u0939\u0923\u093e\u0932\u093e, \\"\u0909\u0924\u0924 \u0928\u093e\u0939\u0940\u0902, \u092e\u093e\u0924\u0924 \u0928\u093e\u0939\u0940\u0902, \u0918\u0947\u0924\u0932\u093e \u0935\u0938\u093e \u091f\u093e\u0915\u0940\u0924 \u0928\u093e\u0939\u0940\u0902.\\" \u0924\u0947\u0935\u094d\u0939\u093e \u0924\u094d\u092f\u093e \u092e\u094d\u0939\u0923\u093e\u0932\u094d\u092f\u093e, \\"\u0936\u094d\u0930\u093e\u0935\u0923\u092e\u093e\u0938 \u092f\u0947\u0908\u0932, \u0924\u0947\u0935\u094d\u0939\u093e\u0902 \u092a\u0939\u093f\u0932\u094d\u092f\u093e \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u0940\u0902 \u092e\u094c\u0928\u094d\u092f\u093e\u0928 (\u092e\u0941\u0915\u093e\u091f\u094d\u092f\u093e\u0928) \u0909\u0920\u093e\u0935\u0902, \u0938\u091a\u0940\u0933 (\u0935\u0938\u094d\u0924\u094d\u0930\u093e\u0938\u0939\u093f\u0924) \u0938\u094d\u0928\u093e\u0928 \u0915\u0930\u093e\u0935\u0902, \u0905\u0917\u094d\u0930\u094b\u0926\u0915 \u092a\u093e\u0923\u0940 \u0906\u0923\u093e\u0935\u0902. \u0935\u093f\u0921\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0928\u093e\u0935\u0930 \u0930\u0915\u094d\u0924\u091a\u0902\u0926\u0928\u093e\u091a\u0940 \u0906\u0926\u093f\u0924\u094d\u092f\u0930\u093e\u0923\u0942\u092c\u093e\u0908 \u0915\u093e\u0922\u093e\u0935\u0940. \u0938\u0939\u093e \u0930\u0947\u0918\u093e\u0902\u091a\u0902 \u092e\u0902\u0921\u0933 \u0915\u0930\u093e\u0935\u0902, \u0938\u0939\u093e \u0938\u0941\u0924\u093e\u0902\u091a\u093e \u0924\u093e\u0924\u0942 \u0915\u0930\u093e\u0935\u093e. \u0924\u094d\u092f\u093e\u0932\u093e \u0938\u0939\u093e \u0917\u093e\u0920\u0940 \u0926\u094d\u092f\u093e\u0935\u094d\u092f\u093e. \u092a\u093e\u0928\u092b\u0942\u0932 \u0935\u0939\u093e\u0935, \u092a\u0942\u091c\u093e \u0915\u0930\u093e\u0935\u0940. \u092a\u093e\u0928\u093e\u091a\u093e \u0935\u093f\u0921\u093e, \u092b\u0941\u0932\u093e\u0902\u091a\u093e \u091d\u0947\u0932\u093e, \u0926\u0936\u093e\u0902\u0917\u093e\u091a\u093e \u0927\u0942\u092a, \u0917\u0941\u0933\u093e\u0916\u094b\u092c\u0930\u094d\u200d\u092f\u093e\u091a\u093e \u0928\u0948\u0935\u0947\u0926\u094d\u092f \u0926\u093e\u0916\u0935\u093e\u0935\u093e, \u0938\u0939\u093e \u092e\u093e\u0938 \u091a\u093e\u0933\u093e\u0935\u0940, \u0938\u0939\u093e \u092e\u093e\u0938 \u092a\u093e\u0933\u093e\u0935\u0940, \u092e\u093e\u0918\u0940 \u0930\u0925\u0938\u092a\u094d\u0924\u092e\u0940\u0902 \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u0915\u0930\u093e\u0935. \u0938\u0902\u092a\u0942\u0930\u094d\u0923\u093e\u0932\u093e \u0915\u093e\u092f \u0915\u0930\u093e\u0935\u0902? \u0917\u0941\u0933\u093e\u091a\u094d\u092f\u093e \u092a\u094b\u0933\u094d\u092f\u093e, \u092c\u094b\u091f\u0935\u094d\u092f\u093e\u0902\u091a\u0940 \u0916\u0940\u0930, \u0932\u094b\u0923\u0915\u0921 \u0924\u0942\u092a, \u092e\u0947\u0939\u0942\u0923 \u091c\u0947\u0935\u0942 \u0938\u093e\u0902\u0917\u093e\u0935. \u0905\u0938\u0947\u0932 \u0924\u0930 \u091a\u093f\u0930\u091a\u094b\u0933\u0940 \u0926\u094d\u092f\u093e\u0935\u0940, \u0928\u0938\u0947\u0932 \u0924\u0930 \u091c\u094b\u0921\u0917\u0933\u0938\u0930\u0940 \u0926\u094d\u092f\u093e\u0935\u0940, \u0924\u0940 \u0928\u0938\u0947\u0932 \u0924\u0930 \u0926\u094b\u0928 \u092a\u0948\u0938\u0947 \u0926\u0915\u094d\u0937\u093f\u0923\u093e \u0926\u094d\u092f\u093e\u0935\u0940 \u0906\u0923\u093f \u0906\u092a\u0932\u094d\u092f\u093e \u0935\u0902\u0936\u093e\u091a \u0909\u0926\u094d\u092f\u093e\u092a\u0928 \u0915\u0930\u093e\u0935.\\" \u0905\u0938\u093e \u0935\u0938\u093e \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928 \u0915\u0947\u0932\u093e. \u0924\u094d\u092f\u093e\u0932\u093e \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923 \u092a\u094d\u0930\u0938\u0928\u094d\u0928 \u091d\u093e\u0932\u093e. \u092d\u093e\u0917\u094d\u092f\u0932\u0915\u094d\u0937\u094d\u092e\u0940 \u0906\u0932\u0940. \u0924\u0947\u0935\u094d\u0939\u093e \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0928\u0947 \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0932\u093e \u092c\u094b\u0932\u093e\u0935\u0923 \u0927\u093e\u0921\u0932\u0902, \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u091c\u093e\u0924\u0947 \u0935\u0947\u0933\u0947\u0938 \u092d\u093f\u090a\u0902 \u0932\u093e\u0917\u0932\u093e. \u0915\u093e\u092a\u0942 \u0932\u093e\u0917\u0932\u093e. \u0924\u0947\u0935\u094d\u0939\u093e \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0928 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0902, \\" \u092d\u093f\u090a \u0928\u0915\u093e, \u0915\u093e\u092a\u0942 \u0928\u0915\u093e, \u0924\u0941\u092e\u091a\u094d\u092f\u093e \u092e\u0941\u0932\u0940 \u0906\u092e\u091a\u0947 \u092f\u0947\u0925\u0947 \u0926\u094d\u092f\u093e\\" \\"\u0906\u092e\u091a\u094d\u092f\u093e \u092e\u0941\u0932\u0940 \u0917\u0930\u0940\u092c\u093e\u091a\u094d\u092f\u093e, \u0924\u0941\u092e\u091a\u094d\u092f\u093e \u0918\u0930\u0940\u0902 \u0915\u0936\u093e \u0926\u094d\u092f\u093e\u0935\u094d\u092f\u093e? \u0926\u093e\u0938\u0940 \u0915\u0930\u093e\u0932, \u092c\u091f\u0915\u0940 \u0915\u0930\u093e\u0932.\\" \u0930\u093e\u0923\u0940 \u092e\u094d\u0939\u0923\u093e\u0932\u0940, \\" \u0926\u093e\u0938\u0940 \u0915\u0930\u0940\u0924 \u0928\u093e\u0939\u0940, \u092c\u091f\u0915\u0940 \u0915\u0930\u0940\u0924 \u0928\u093e\u0939\u0940\u0902. \u0930\u093e\u091c\u093e\u091a\u0940 \u0930\u093e\u0923\u0940 \u0915\u0930\u0942, \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u0940 \u0930\u093e\u0923\u0940 \u0915\u0930\u0942.\\"","source":"@site/docs/katha/adityaranubai.md","sourceDirName":"katha","slug":"/aditya-ranubai-devanchi-kahani","permalink":"/aditya-ranubai-devanchi-kahani","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"slug":"/aditya-ranubai-devanchi-kahani","verified":true},"sidebar":"tutorialSidebar","previous":{"title":"\u0936\u094d\u0930\u0940 \u0917\u0923\u092a\u0924\u0940\u091a\u0940 \u0915\u0939\u093e\u0923\u0940","permalink":"/ganapati-kahani"},"next":{"title":"\u0927\u0930\u093f\u0924\u094d\u0930\u0940\u091a\u0940 \u0915\u0939\u093e\u0923\u0940","permalink":"/dharitri-devanchi-kahani"}}');var i=e(74848),r=e(28453);const s={slug:"/aditya-ranubai-devanchi-kahani",verified:!0},c="\u0906\u0926\u093f\u0924\u094d\u092f\u0930\u093e\u0923\u0942\u092c\u093e\u0908\u091a\u0940 (\u092a\u094c\u0937 \u0930\u0935\u0940\u0935\u093e\u0930\u091a\u0940) \u0915\u0939\u093e\u0923\u0940",d={},h=[];function o(n){const a={h1:"h1",header:"header",p:"p",...(0,r.R)(),...n.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.header,{children:(0,i.jsx)(a.h1,{id:"\u0906\u0926\u093f\u0924\u094d\u092f\u0930\u093e\u0923\u0942\u092c\u093e\u0908\u091a\u0940-\u092a\u094c\u0937-\u0930\u0935\u0940\u0935\u093e\u0930\u091a\u0940-\u0915\u0939\u093e\u0923\u0940",children:"\u0906\u0926\u093f\u0924\u094d\u092f\u0930\u093e\u0923\u0942\u092c\u093e\u0908\u091a\u0940 (\u092a\u094c\u0937 \u0930\u0935\u0940\u0935\u093e\u0930\u091a\u0940) \u0915\u0939\u093e\u0923\u0940"})}),"\n",(0,i.jsx)(a.p,{children:'\u0910\u0915\u093e \u0906\u0926\u093f\u0924\u094d\u092f\u0930\u093e\u0923\u0942\u092c\u093e\u0908 \u0924\u0941\u092e\u091a\u0940 \u0915\u0939\u093e\u0923\u0940. \u0906\u091f\u092a\u093e\u091f \u0928\u0917\u0930 \u0939\u094b\u0924\u0902. \u0924\u094d\u092f\u093e \u0928\u0917\u0930\u093e\u0924 \u090f\u0915 \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u0939\u094b\u0924\u093e. \u0924\u094b \u0928\u093f\u0924\u094d\u092f \u0938\u092e\u093f\u0927\u093e, \u092b\u0941\u0932\u0902, \u0926\u0942\u0930\u094d\u0935\u093e, \u0906\u0923\u093e\u092f\u0932\u093e \u0930\u093e\u0928\u093e\u0902\u0924 \u091c\u093e\u0924 \u0905\u0938\u0947. \u0924\u093f\u0925\u0902 \u0928\u093e\u0917\u0915\u0928\u094d\u092f\u093e \u0926\u0947\u0935\u0915\u0928\u094d\u092f\u093e \u0935\u0938\u093e \u0935\u0938\u0924 \u0939\u094b\u0924\u094d\u092f\u093e. \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928\u0902 \u0935\u093f\u091a\u093e\u0930\u0932\u0902, "\u0915\u093e\u092f \u0917 \u092c\u093e\u092f\u093e\u0902\u0928\u094b\u0902, \u0915\u0938\u0932\u093e \u0935\u0938\u093e \u0935\u0938\u0924\u093e\u0902? \u0924\u094b \u092e\u0932\u093e \u0938\u093e\u0902\u0917\u093e." " \u0924\u0941\u0932\u093e \u0930\u0947 \u0935\u0938\u093e \u0915\u0936\u093e\u0932\u093e \u0939\u0935\u093e? \u0909\u0924\u0936\u0940\u0932, \u092e\u093e\u0924\u0936\u0940\u0932, \u0918\u0947\u0924\u0932\u093e \u0935\u0938\u093e \u091f\u093e\u0915\u0942\u0928 \u0926\u0947\u0936\u0940\u0932." \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u092e\u094d\u0939\u0923\u093e\u0932\u093e, "\u0909\u0924\u0924 \u0928\u093e\u0939\u0940\u0902, \u092e\u093e\u0924\u0924 \u0928\u093e\u0939\u0940\u0902, \u0918\u0947\u0924\u0932\u093e \u0935\u0938\u093e \u091f\u093e\u0915\u0940\u0924 \u0928\u093e\u0939\u0940\u0902." \u0924\u0947\u0935\u094d\u0939\u093e \u0924\u094d\u092f\u093e \u092e\u094d\u0939\u0923\u093e\u0932\u094d\u092f\u093e, "\u0936\u094d\u0930\u093e\u0935\u0923\u092e\u093e\u0938 \u092f\u0947\u0908\u0932, \u0924\u0947\u0935\u094d\u0939\u093e\u0902 \u092a\u0939\u093f\u0932\u094d\u092f\u093e \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u0940\u0902 \u092e\u094c\u0928\u094d\u092f\u093e\u0928 (\u092e\u0941\u0915\u093e\u091f\u094d\u092f\u093e\u0928) \u0909\u0920\u093e\u0935\u0902, \u0938\u091a\u0940\u0933 (\u0935\u0938\u094d\u0924\u094d\u0930\u093e\u0938\u0939\u093f\u0924) \u0938\u094d\u0928\u093e\u0928 \u0915\u0930\u093e\u0935\u0902, \u0905\u0917\u094d\u0930\u094b\u0926\u0915 \u092a\u093e\u0923\u0940 \u0906\u0923\u093e\u0935\u0902. \u0935\u093f\u0921\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0928\u093e\u0935\u0930 \u0930\u0915\u094d\u0924\u091a\u0902\u0926\u0928\u093e\u091a\u0940 \u0906\u0926\u093f\u0924\u094d\u092f\u0930\u093e\u0923\u0942\u092c\u093e\u0908 \u0915\u093e\u0922\u093e\u0935\u0940. \u0938\u0939\u093e \u0930\u0947\u0918\u093e\u0902\u091a\u0902 \u092e\u0902\u0921\u0933 \u0915\u0930\u093e\u0935\u0902, \u0938\u0939\u093e \u0938\u0941\u0924\u093e\u0902\u091a\u093e \u0924\u093e\u0924\u0942 \u0915\u0930\u093e\u0935\u093e. \u0924\u094d\u092f\u093e\u0932\u093e \u0938\u0939\u093e \u0917\u093e\u0920\u0940 \u0926\u094d\u092f\u093e\u0935\u094d\u092f\u093e. \u092a\u093e\u0928\u092b\u0942\u0932 \u0935\u0939\u093e\u0935, \u092a\u0942\u091c\u093e \u0915\u0930\u093e\u0935\u0940. \u092a\u093e\u0928\u093e\u091a\u093e \u0935\u093f\u0921\u093e, \u092b\u0941\u0932\u093e\u0902\u091a\u093e \u091d\u0947\u0932\u093e, \u0926\u0936\u093e\u0902\u0917\u093e\u091a\u093e \u0927\u0942\u092a, \u0917\u0941\u0933\u093e\u0916\u094b\u092c\u0930\u094d\u200d\u092f\u093e\u091a\u093e \u0928\u0948\u0935\u0947\u0926\u094d\u092f \u0926\u093e\u0916\u0935\u093e\u0935\u093e, \u0938\u0939\u093e \u092e\u093e\u0938 \u091a\u093e\u0933\u093e\u0935\u0940, \u0938\u0939\u093e \u092e\u093e\u0938 \u092a\u093e\u0933\u093e\u0935\u0940, \u092e\u093e\u0918\u0940 \u0930\u0925\u0938\u092a\u094d\u0924\u092e\u0940\u0902 \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u0915\u0930\u093e\u0935. \u0938\u0902\u092a\u0942\u0930\u094d\u0923\u093e\u0932\u093e \u0915\u093e\u092f \u0915\u0930\u093e\u0935\u0902? \u0917\u0941\u0933\u093e\u091a\u094d\u092f\u093e \u092a\u094b\u0933\u094d\u092f\u093e, \u092c\u094b\u091f\u0935\u094d\u092f\u093e\u0902\u091a\u0940 \u0916\u0940\u0930, \u0932\u094b\u0923\u0915\u0921 \u0924\u0942\u092a, \u092e\u0947\u0939\u0942\u0923 \u091c\u0947\u0935\u0942 \u0938\u093e\u0902\u0917\u093e\u0935. \u0905\u0938\u0947\u0932 \u0924\u0930 \u091a\u093f\u0930\u091a\u094b\u0933\u0940 \u0926\u094d\u092f\u093e\u0935\u0940, \u0928\u0938\u0947\u0932 \u0924\u0930 \u091c\u094b\u0921\u0917\u0933\u0938\u0930\u0940 \u0926\u094d\u092f\u093e\u0935\u0940, \u0924\u0940 \u0928\u0938\u0947\u0932 \u0924\u0930 \u0926\u094b\u0928 \u092a\u0948\u0938\u0947 \u0926\u0915\u094d\u0937\u093f\u0923\u093e \u0926\u094d\u092f\u093e\u0935\u0940 \u0906\u0923\u093f \u0906\u092a\u0932\u094d\u092f\u093e \u0935\u0902\u0936\u093e\u091a \u0909\u0926\u094d\u092f\u093e\u092a\u0928 \u0915\u0930\u093e\u0935." \u0905\u0938\u093e \u0935\u0938\u093e \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928 \u0915\u0947\u0932\u093e. \u0924\u094d\u092f\u093e\u0932\u093e \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923 \u092a\u094d\u0930\u0938\u0928\u094d\u0928 \u091d\u093e\u0932\u093e. \u092d\u093e\u0917\u094d\u092f\u0932\u0915\u094d\u0937\u094d\u092e\u0940 \u0906\u0932\u0940. \u0924\u0947\u0935\u094d\u0939\u093e \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0928\u0947 \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0932\u093e \u092c\u094b\u0932\u093e\u0935\u0923 \u0927\u093e\u0921\u0932\u0902, \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u091c\u093e\u0924\u0947 \u0935\u0947\u0933\u0947\u0938 \u092d\u093f\u090a\u0902 \u0932\u093e\u0917\u0932\u093e. \u0915\u093e\u092a\u0942 \u0932\u093e\u0917\u0932\u093e. \u0924\u0947\u0935\u094d\u0939\u093e \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0928 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0902, " \u092d\u093f\u090a \u0928\u0915\u093e, \u0915\u093e\u092a\u0942 \u0928\u0915\u093e, \u0924\u0941\u092e\u091a\u094d\u092f\u093e \u092e\u0941\u0932\u0940 \u0906\u092e\u091a\u0947 \u092f\u0947\u0925\u0947 \u0926\u094d\u092f\u093e" "\u0906\u092e\u091a\u094d\u092f\u093e \u092e\u0941\u0932\u0940 \u0917\u0930\u0940\u092c\u093e\u091a\u094d\u092f\u093e, \u0924\u0941\u092e\u091a\u094d\u092f\u093e \u0918\u0930\u0940\u0902 \u0915\u0936\u093e \u0926\u094d\u092f\u093e\u0935\u094d\u092f\u093e? \u0926\u093e\u0938\u0940 \u0915\u0930\u093e\u0932, \u092c\u091f\u0915\u0940 \u0915\u0930\u093e\u0932." \u0930\u093e\u0923\u0940 \u092e\u094d\u0939\u0923\u093e\u0932\u0940, " \u0926\u093e\u0938\u0940 \u0915\u0930\u0940\u0924 \u0928\u093e\u0939\u0940, \u092c\u091f\u0915\u0940 \u0915\u0930\u0940\u0924 \u0928\u093e\u0939\u0940\u0902. \u0930\u093e\u091c\u093e\u091a\u0940 \u0930\u093e\u0923\u0940 \u0915\u0930\u0942, \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u0940 \u0930\u093e\u0923\u0940 \u0915\u0930\u0942."\n\u092e\u093e\u0930\u094d\u0917\u0947\u0936\u094d\u0935\u0930\u093e\u091a\u093e \u092e\u0939\u093f\u0928\u093e \u0906\u0932\u093e. \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0928\u0902 \u0932\u0917\u0940\u0928 \u0915\u0930\u0942\u0928 \u092e\u0941\u0932\u0940 \u0926\u093f\u0932\u094d\u092f\u093e, \u090f\u0915 \u0930\u093e\u091c\u093e\u091a\u0947 \u0918\u0930\u0940\u0902 \u0926\u093f\u0932\u0940. \u0926\u0941\u0938\u0930\u0940 \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u0947 \u0918\u0930\u0940\u0902 \u0926\u093f\u0932\u0940. \u0917\u0947\u0932\u094d\u092f\u093e \u092a\u093e\u0935\u0932\u0940\u0902 \u092e\u0941\u0932\u0940\u0902\u091a\u093e \u0938\u092e\u093e\u091a\u093e\u0930 \u0918\u0947\u0924\u0932\u093e \u0928\u093e\u0939\u0940\u0902. \u092c\u093e\u0930\u093e \u0935\u0930\u094d\u0937\u093e\u0902\u0928\u0940\u0902 \u0938\u092e\u093e\u091a\u093e\u0930\u093e\u0938 \u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923 \u0928\u093f\u0918\u093e\u0932\u093e. \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0918\u0930\u0940 \u0917\u0947\u0932\u093e. \u0932\u0947\u0915\u0940\u0928 \u092c\u0938\u093e\u092f\u0932\u093e \u092a\u093e\u091f \u0926\u093f\u0932\u093e, \u092a\u093e\u092f \u0927\u0941\u0935\u093e\u092f\u0932\u093e \u092a\u093e\u0923\u0940 \u0926\u093f\u0932\u0902. "\u092c\u093e\u092c \u092c\u093e\u092c\u093e, \u0917\u0942\u0933 \u0916\u093e \u092a\u093e\u0923\u0940 \u092a\u094d\u092f\u093e." \u0917\u0942\u0933 \u0916\u093e\u0924 \u0928\u093e\u0939\u0940\u0902, \u092a\u093e\u0923\u0940 \u092a\u0940\u0924 \u0928\u093e\u0939\u0940\u0902. \u092e\u093e\u091d\u0940 \u0915\u0939\u093e\u0923\u0940 \u0915\u0930\u093e\u092f\u091a\u0940 \u0906\u0939\u0947 \u0924\u0940 \u0924\u0942\u0902 \u0910\u0915." \u0924\u0941\u091d\u0940 \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u093e\u092f\u0932\u093e \u092e\u0932\u093e \u0935\u0947\u0933 \u0928\u093e\u0939\u0940\u0902. \u0930\u093e\u091c\u093e \u092a\u093e\u0930\u0927\u0940\u0932\u093e \u091c\u093e\u0923\u093e\u0930 \u0906\u0939\u0947. \u0924\u094d\u092f\u093e\u0932\u093e \u091c\u0947\u0935\u093e\u092f\u0932\u093e \u0909\u0936\u0940\u0930 \u0939\u094b\u0908\u0932. \u0924\u094b\u091a \u0924\u094d\u092f\u093e\u091a\u0947 \u092e\u0928\u093e\u0902\u0924 \u0930\u093e\u0917 \u0906\u0932\u093e. \u0924\u0947\u0925\u0942\u0928 \u0928\u093f\u0918\u093e\u0932\u093e \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u094d\u092f\u093e \u0918\u0930\u0940 \u0917\u0947\u0932\u093e. \u0924\u093f\u0928\u0902 \u092a\u093e\u0939\u093f\u0932\u0902, \u0906\u092a\u0932\u093e \u092c\u093e\u092a \u0906\u0932\u093e. \u092e\u094d\u0939\u0923\u0942\u0928 \u092c\u0938\u093e\u092f\u0932\u093e \u092a\u093e\u091f \u0926\u093f\u0932\u093e, \u092a\u093e\u092f \u0927\u0941\u0935\u093e\u092f\u0932\u093e \u092a\u093e\u0923\u0940 \u0926\u093f\u0932\u0902. "\u092c\u093e\u092c\u093e, \u092c\u093e\u092c\u093e, \u0917\u0942\u0933 \u0916\u093e, \u092a\u093e\u0923\u0940 \u092a\u094d\u092f\u093e." " \u0917\u0942\u0933 \u0916\u093e\u0924 \u0928\u093e\u0939\u0940 \u092a\u093e\u0923\u0940 \u092a\u093f\u0924 \u0928\u093e\u0939\u0940, \u092e\u093e\u091d\u0940 \u0915\u0939\u093e\u0923\u0940 \u0915\u0930\u093e\u092f\u091a\u0940 \u0906\u0939\u0947, \u0924\u0940 \u0924\u0942\u0902 \u0905\u0917\u094b\u0926\u0930 \u0910\u0915. " \u0924\u0941\u091d\u0940 \u0915\u0939\u093e\u0923\u0940 \u0928\u0915\u094b \u0910\u0915\u0942 \u0924\u0930 \u0915\u094b\u0923\u093e\u091a\u0940 \u0910\u0915\u0942?" \u0918\u0930\u093e\u0902\u0924 \u0917\u0947\u0932\u0940, \u0909\u0924\u0930\u0921\u0940\u091a\u0940 \u0938\u0939\u093e \u092e\u094b\u0924\u094d\u092f\u0947 \u0906\u0923\u0932\u0940. \u0924\u0940\u0928 \u0906\u092a\u0923 \u0918\u0947\u0924\u0932\u0940\u0902. \u0924\u0940\u0928 \u092c\u093e\u092a\u093e\u091a\u094d\u092f\u093e \u0939\u093e\u0924\u093e\u0902\u0924 \u0926\u093f\u0932\u0940\u0902. \u0924\u094d\u092f\u093e\u0928\u0947 \u092e\u0928\u094b\u092d\u093e\u0935\u0947 \u0915\u0939\u093e\u0923\u0940 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0940 \u0932\u0947\u0915\u0940\u0928\u0902 \u091a\u093f\u0924\u094d\u0924\u092d\u093e\u0935\u0947 \u0924\u0940 \u0910\u0915\u0932\u0940. \u0928\u0902\u0924\u0930 \u091c\u0947\u0935\u0942\u0928 \u0916\u093e\u090a\u0928 \u092c\u093e\u092a \u0906\u092a\u0932\u094d\u092f\u093e \u0918\u0930\u0940 \u0906\u0932\u093e. \u092c\u093e\u092f\u0915\u094b\u0928\u0902 \u0935\u093f\u091a\u093e\u0930\u0932\u0902, " \u092e\u0941\u0932\u0940\u0902\u091a\u093e \u0938\u092e\u093e\u091a\u093e\u0930 \u0915\u0938\u093e \u0906\u0939\u0947?" \u091c\u093f\u0928\u0902 \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0932\u0940 \u0928\u093e\u0939\u0940\u0902, \u0924\u0940 \u0926\u093e\u0930\u093f\u0926\u094d\u0930\u092f\u093e\u0928\u0947 \u092a\u0940\u0921\u0932\u0940. \u0926\u0941\u0903\u0916\u093e\u0928\u0902 \u0935\u094d\u092f\u093e\u092a\u0932\u0940. \u0930\u093e\u091c\u093e \u092e\u0941\u0932\u0916\u093e\u0935\u0930 \u0928\u093f\u0918\u0942\u0928 \u0917\u0947\u0932\u093e. \u091c\u093f\u0928\u0902 \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0932\u0940 \u0939\u094b\u0924\u0940, \u0924\u0940 \u092d\u093e\u0917\u094d\u092f\u0928\u0902 \u0928\u093e\u0902\u0926\u0924 \u0906\u0939\u0947." \u0907\u0915\u0921\u0947 \u0926\u0930\u093f\u0926\u094d\u0930\u0940 \u091c\u0940 \u091d\u093e\u0932\u0940 \u0939\u094b\u0924\u0940, \u0924\u093f\u0928\u0902 \u0906\u092a\u0932\u094d\u092f\u093e \u0932\u0947\u0915\u093e\u0932\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0947. "\u092e\u093e\u0935\u0936\u0940 \u0918\u0928\u0918\u094b\u0930 \u0928\u093e\u0902\u0926\u0924 \u0906\u0939\u0947, \u0924\u093f\u0915\u0921\u0947 \u091c\u093e\u090a\u0928 \u0915\u093e\u0939\u0940 \u0926\u093f\u0932\u0902 \u0924\u0930 \u0918\u0947\u090a\u0928 \u092f\u0947."\n\u092a\u0939\u093f\u0932\u094d\u092f\u093e \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u0940 \u092a\u0939\u093f\u0932\u093e \u092e\u0941\u0932\u0917\u093e \u0909\u0920\u0932\u093e, \u0924\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0933\u0940 \u091c\u093e\u090a\u0928 \u0909\u092d\u093e \u0930\u093e\u0939\u093f\u0932\u093e." \u0905\u0917 \u0905\u0917 \u0926\u093e\u0938\u0940\u0902\u0928\u094b, \u0924\u0941\u092e\u094d\u0939\u0940 \u0926\u093e\u0938\u0940 \u0915\u094b\u0923\u093e\u091a\u094d\u092f\u093e?" " \u0906\u092e\u094d\u0939\u0940 \u0926\u093e\u0938\u0940 \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u094d\u092f\u093e. \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0932\u093e \u091c\u093e\u090a\u0928 \u0938\u093e\u0902\u0917\u093e, \u0924\u0941\u092e\u091a\u094d\u092f\u093e \u092c\u0939\u093f\u0923\u0940\u091a\u093e \u092e\u0941\u0932\u0917\u093e \u0906\u0932\u093e \u0906\u0939\u0947." "\u0915\u0938\u093e \u0906\u0932\u093e \u0906\u0939\u0947? \u0924\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0933\u0940\u0932\u093e \u0909\u092d\u093e \u0930\u093e\u0939\u093f\u0932\u093e \u0906\u0939\u0947." \u2018\u092a\u0930\u0938\u0926\u093e\u0930\u0928 \u0918\u0947\u090a\u0928 \u092f\u093e.\u2019 \u092a\u0930\u0938\u0926\u093e\u0930\u093e\u0928\u0902 \u0918\u0947\u090a\u0928 \u0906\u0932\u094d\u092f\u093e. \u0928\u094d\u0939\u093e\u090a \u092e\u093e\u0916\u0942 \u0918\u093e\u0924\u0932\u0902, \u092a\u0940\u0924\u093e\u0902\u092c\u0930 \u0928\u0947\u0938\u093e\u092f\u0932\u093e \u0926\u093f\u0932\u093e, \u091c\u0947\u0935\u0942 \u0916\u093e\u090a \u0918\u093e\u0924\u0932\u0902. \u0915\u094b\u0939\u094b\u0933\u093e \u092a\u094b\u0916\u0930\u0932\u093e, \u0939\u094b\u0928\u092e\u094b\u0939\u094b\u0930\u093e \u092d\u0930\u0932\u094d\u092f\u093e. "\u0935\u093e\u091f\u0947\u0938 \u0906\u092a\u0932\u093e \u091c\u093e\u090a \u0932\u093e\u0917\u0932\u093e. \u0924\u094b \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923 \u092e\u093e\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u0930\u0942\u092a\u093e\u0928\u0902 \u0906\u0932\u093e. \u0939\u093e\u0924\u0940\u091a\u093e \u0915\u094b\u0939\u094b\u0933\u093e \u0915\u093e\u0922\u0942\u0928 \u0928\u0947\u0932\u093e. \u0918\u0930\u0940 \u0917\u0947\u0932\u093e. \u0906\u0908\u0928\u0902 \u0935\u093f\u091a\u093e\u0930\u0932\u0902, " \u0915\u093e\u092f \u0930\u0947 \u092c\u093e\u092c\u093e, \u092e\u093e\u0935\u0936\u0940\u0928\u0902 \u0915\u093e\u092f \u0926\u093f\u0932\u0902?" \u0926\u0948\u0935\u0947 \u0926\u093f\u0932\u0902, \u0915\u0930\u094d\u092e\u093e\u0928\u0902 \u0928\u0947\u0932\u0902. \u0915\u0930\u094d\u092e\u093e\u091a \u092b\u0933 \u092a\u0941\u0922\u0902 \u0909\u092d\u0902 \u0930\u093e\u0939\u093f\u0932\u0902. \u092e\u093e\u0935\u0936\u0940\u0928\u0902 \u0926\u093f\u0932\u0902 \u0939\u094b\u0924\u0902. \u092a\u0923 \u0938\u0930\u094d\u0935 \u0917\u0947\u0932\u0902.'}),"\n",(0,i.jsx)(a.p,{children:'\u092a\u0941\u0922\u0902 \u0926\u0941\u0938\u0930\u094d\u200d\u092f\u093e \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u0940 \u0926\u0941\u0938\u0930\u093e \u092e\u0941\u0932\u0917\u093e \u0917\u0947\u0932\u093e. \u0924\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0933\u0940 \u091c\u093e\u090a\u0928 \u0909\u092d\u093e \u0930\u093e\u0939\u093f\u0932\u093e. "\u0905\u0917 \u0905\u0917 \u0926\u093e\u0938\u0940\u0928\u094b, \u0924\u0941\u092e\u094d\u0939\u0940 \u0926\u093e\u0938\u0940 \u0915\u094b\u0923\u093e\u091a\u094d\u092f\u093e?" "\u0906\u092e\u094d\u0939\u0940 \u0926\u093e\u0938\u0940 \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u094d\u092f\u093e." \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0932\u093e \u0928\u093f\u0930\u094b\u092a \u0938\u093e\u0902\u0917\u093e. \u0924\u094d\u092f\u093e\u0902\u0928\u0940 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u093e. \u092e\u0917 \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0928\u0902 \u0924\u094d\u092f\u093e\u0932\u093e \u0918\u0930\u0940 \u0928\u0947\u090a\u0928 \u0928\u094d\u0939\u093e\u090a \u092e\u093e\u0916\u0942 \u0918\u093e\u0924\u0932\u0902 \u092a\u0940\u0924\u093e\u0902\u092c\u0930 \u0928\u0947\u0938\u093e\u092f\u0932\u093e \u0926\u093f\u0932\u093e, \u091c\u0947\u0935\u0942 \u0916\u093e\u090a \u0918\u093e\u0924\u0932\u0902. \u0915\u093e\u0920\u0940 \u092a\u094b\u0916\u0930\u0942\u0928 \u0939\u094b\u0928\u093e\u092e\u094b\u0939\u094b\u0930\u093e\u0902\u0928\u0940\u0902 \u092d\u0930\u0942\u0928 \u0926\u093f\u0932\u0940. " \u092c\u093e\u092c\u093e, \u0920\u0947\u0935\u0942 \u0928\u0915\u094b. \u0935\u093f\u0938\u0930\u0942 \u0928\u0915\u094b. \u091c\u0924\u0928 \u0915\u0930\u0942\u0928 \u0918\u0930\u0940 \u0918\u0947\u090a\u0928 \u091c\u093e, " \u092e\u094d\u0939\u0923\u0942\u0928 \u0938\u093e\u0902\u0917\u093f\u0924\u0932. \u0935\u093e\u091f\u0947\u0924 \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923 \u0917\u0941\u0930\u093e\u0916\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u0930\u0942\u092a\u093e\u0928\u0902 \u0906\u0932\u093e, \u0939\u093e\u0924\u091a\u0940 \u0915\u093e\u0920\u0940 \u0915\u093e\u0922\u0942\u0928 \u0918\u0947\u0924\u0932\u0940. \u0918\u0930\u0940 \u0917\u0947\u0932\u093e, \u091d\u093e\u0932\u0947\u0932\u0940 \u0917\u094b\u0937\u094d\u091f \u0930\u093e\u0923\u0940\u0932\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0940. "\u0926\u0948\u0935\u0947 \u0926\u093f\u0932\u0902, \u0924\u0947 \u0938\u0930\u094d\u0935 \u0915\u0930\u094d\u092e\u093e\u0928\u0902 \u0928\u0947\u0932\u0902."'}),"\n",(0,i.jsx)(a.p,{children:'\u092a\u0941\u0922\u0902 \u0924\u093f\u0938\u0930\u0947 \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u0940 \u0924\u093f\u0938\u0930\u093e \u092e\u0941\u0932\u0917\u093e \u0917\u0947\u0932\u093e, \u0924\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0933\u0940 \u0909\u092d\u093e \u0930\u093e\u0939\u093f\u0932\u093e. \u0924\u094d\u092f\u093e\u0932\u093e\u0939\u0940 \u092a\u0939\u093f\u0932\u094d\u092f\u093e\u0938\u0930\u0916\u0902 \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u0947 \u0918\u0930\u0940 \u0928\u0947\u090a\u0928 \u0928\u094d\u0939\u093e\u090a\u0902 \u092e\u093e\u0916\u0942 \u0918\u093e\u0924\u0932\u0902, \u092a\u0940\u0924\u093e\u0902\u092c\u0930 \u0928\u0947\u0938\u093e\u092f\u0932\u093e \u0926\u093f\u0932\u093e, \u091c\u0947\u0935\u0942 \u0916\u093e\u090a \u0918\u093e\u0924\u0932\u0902, \u0928\u093e\u0930\u0933 \u092a\u094b\u0916\u0930\u0942\u0928 \u0939\u094b\u0928\u092e\u094b\u0939\u094b\u0930\u093e\u0902\u0928\u0940 \u092d\u0930\u0942\u0928 \u0926\u093f\u0932\u093e. " \u0920\u0947\u0935\u0942 \u0928\u0915\u094b, \u0935\u093f\u0938\u0930\u0942 \u0928\u0915\u094b." \u092e\u094d\u0939\u0923\u0942\u0928 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0902, \u0918\u0930\u0940 \u091c\u093e\u0924\u093e\u0928\u093e \u0935\u093f\u0939\u093f\u0930\u0940\u0924 \u0909\u0924\u0930\u0932\u093e. \u0924\u094b \u0917\u0921\u092c\u0921\u0942\u0928 \u0935\u093f\u0939\u093f\u0930\u0940\u0924 \u092a\u0921\u0932\u093e. \u0918\u0930\u0940 \u0917\u0947\u0932\u093e. \u0906\u0908\u0928\u0902 \u0935\u093f\u091a\u093e\u0930\u0932\u0902. " \u0915\u093e\u092f \u0930\u0947 \u092c\u093e\u092c\u093e, \u092e\u093e\u0935\u0936\u0940\u0928\u0902 \u0915\u093e\u092f \u0926\u093f\u0932\u0902?" \u0906\u0908 \u0917, \u092e\u093e\u0935\u0936\u0940\u0928\u0902 \u0926\u093f\u0932\u0902, \u092a\u0923 \u0926\u0948\u0935\u093e\u0928\u0902 \u0924\u0947\u0902 \u0938\u0930\u094d\u0935 \u092c\u0941\u0921\u093e\u0932\u0902."'}),"\n",(0,i.jsx)(a.p,{children:'\u091a\u0935\u0925\u094d\u092f\u093e \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u0940 \u091a\u0935\u0925\u093e \u092e\u0941\u0932\u0917\u093e \u0917\u0947\u0932\u093e. \u0924\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0933\u0940 \u0909\u092d\u093e \u0930\u093e\u0939\u093f\u0932\u093e. \u0924\u094d\u092f\u093e\u0932\u093e\u0939\u0940 \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0928\u0902 \u0918\u0930\u0940\u0902 \u0928\u0947\u090a\u0928 \u0928\u094d\u0939\u093e\u090a \u092e\u093e\u0916\u0942 \u0918\u093e\u0924\u0932\u0902, \u092a\u0940\u0924\u093e\u0902\u092c\u0930 \u0928\u0947\u0938\u093e\u092f\u0932\u093e \u0926\u093f\u0932\u093e. \u091c\u0947\u0935\u0942\u0902 \u0916\u093e\u090a \u0918\u093e\u0924\u0932\u0902. \u0924\u094d\u092f\u093e\u0932\u093e \u0926\u0939\u094d\u092f\u093e\u091a\u0940 \u0936\u093f\u0926\u094b\u0930\u0940 \u0939\u094b\u0928\u093e\u092e\u094b\u0939\u094b\u0930\u093e \u0918\u093e\u0932\u0942\u0928 \u092c\u0930\u094b\u092c\u0930 \u0926\u093f\u0932\u0940. \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923 \u0918\u093e\u0930\u0940\u091a\u094d\u092f\u093e \u0930\u0942\u092a\u093e\u0928 \u0906\u0932\u093e. \u0939\u093e\u0924\u091a\u0940 \u0936\u093f\u0926\u094b\u0930\u0940 \u0918\u0947\u090a\u0928 \u0917\u0947\u0932\u093e. \u0918\u0930\u0940 \u0917\u0947\u0932\u093e. \u0906\u0908\u0928\u0902 \u0935\u093f\u091a\u093e\u0930\u0932\u0902, "\u0915\u093e\u092f \u0930\u0947 \u092c\u093e\u092c\u093e, \u092e\u093e\u0935\u0936\u0940\u0928\u0902 \u0915\u093e\u092f \u0926\u093f\u0932\u0902?" "\u0906\u0908 \u092e\u093e\u0935\u0938\u0936\u0940\u0928\u0902 \u0926\u093f\u0932\u0902, \u092a\u0923 \u0926\u0948\u0935\u093e\u0928\u0902 \u0924\u0947 \u0938\u0930\u094d\u0935 \u0928\u0947\u0932\u0902."'}),"\n",(0,i.jsx)(a.p,{children:'\u092a\u093e\u091a\u0935\u094d\u092f\u093e \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u0940\u0902 \u0906\u092a\u0923 \u0909\u0920\u0932\u0940, \u0924\u0933\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u0933\u0940 \u0909\u092d\u0940 \u0930\u093e\u0939\u093f\u0932\u0940. \u0926\u093e\u0938\u0940\u0928\u0940 \u0924\u093f\u091a\u093e \u0928\u093f\u0930\u094b\u092a \u0924\u093f\u091a\u094d\u092f\u093e \u092c\u0939\u093f\u0923\u0940\u0932\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u093e. \u092c\u0939\u093f\u0923\u0940\u0928\u0902 \u0924\u093f\u0932\u093e\u0939\u0940 \u092a\u0930\u0938\u0926\u093e\u0930\u093e\u0928\u0902 \u0918\u0930\u0940\u0902 \u0928\u0947\u0932\u0902. \u0928\u094d\u0939\u093e\u090a\u0902 \u0918\u093e\u0924\u0932\u0902 \u092e\u093e\u0916\u0942\u0902 \u0918\u093e\u0924\u0932\u0902, \u092a\u093e\u091f\u093e\u091a \u092c\u0947\u0938\u093e\u092f\u0932\u093e \u0926\u093f\u0932\u093e. \u092a\u094d\u0930\u0927\u093e\u0928\u093e\u091a\u0940 \u0930\u093e\u0923\u0940 \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u093e\u091a\u0940 \u0915\u0939\u093e\u0923\u0940 \u0915\u0930\u0942 \u0932\u093e\u0917\u0932\u0940. " \u0915\u093e\u092f \u0935\u0938\u093e \u0915\u0930\u0924\u0947\u0938 \u0924\u094b \u092e\u0932\u093e \u0938\u093e\u0902\u0917." \u092c\u0939\u0940\u0923 \u092e\u094d\u0939\u0923\u093e\u0932\u0940, "\u0905\u0902\u0917 \u0905\u0902\u0917 \u091a\u093e\u0902\u0921\u093e\u0933\u0923\u0940, \u092a\u093e\u092a\u093f\u0923\u0940, \u092c\u093e\u092a\u093e\u091a\u0940 \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0932\u0940 \u0928\u093e\u0939\u0940\u0902\u0938, \u092e\u094d\u0939\u0923\u0942\u0928 \u0924\u0941\u0932\u093e \u0926\u0930\u093f\u0926\u094d\u0930 \u0906\u0932\u0902." \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0928\u0902 \u0935\u093f\u091a\u093e\u0930\u0932\u0902, "\u092f\u093e\u0932\u093e \u092c\u0939\u093f\u0923\u0940\u091a\u094d\u092f\u093e \u0918\u0930\u0940\u0902 \u0930\u093e\u0939\u093f\u0932\u0940. \u0936\u094d\u0930\u093e\u0935\u0923\u093e\u0938 \u0906\u0932\u093e. \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u094d\u092f\u093e\u092a\u094d\u0930\u092e\u093e\u0923\u0902 \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923\u093e\u091a\u0940 \u092a\u0942\u091c\u093e \u0915\u0947\u0932\u0940. \u0907\u0915\u0921\u0947 \u0930\u093e\u091c\u093e\u0932\u093e \u092d\u093e\u0917\u094d\u092f \u0906\u0932\u0902. \u0930\u093e\u091c\u093e\u0928\u0902 \u092c\u094b\u0932\u093e\u0935\u0942\u0902 \u0927\u093e\u0921\u0932\u0902. "\u092e\u093e\u0935\u0936\u0940 \u092e\u093e\u0935\u0936\u0940, \u0924\u0941\u0932\u093e \u091b\u0924\u094d\u0930\u0902 \u0906\u0932\u0940\u0902, \u091a\u093e\u092e\u0930\u0902 \u0906\u0932\u0940\u0902, \u092a\u093e\u0908\u0915 \u0906\u0932\u0947, \u092a\u0930\u0935\u0930 \u0906\u0932\u0947." "\u092e\u0932\u093e \u0930\u0947 \u092a\u093e\u092a\u093f\u0923\u0940\u0932\u093e \u091b\u0924\u094d\u0930\u0902 \u0915\u094b\u0920\u0932\u0940? \u091a\u093e\u092e\u0930\u0902 \u0915\u094b\u0920\u0932\u0940\u0902? \u092a\u093e\u0908\u0915 \u0915\u094b\u0920\u0932\u0947? \u092a\u0930\u0935\u0930 \u0915\u094b\u0920\u0947?" \u092c\u093e\u0939\u0947\u0930 \u091c\u093e\u090a\u0928 \u0926\u093e\u0930\u093e\u0936\u0940\u0902 \u092c\u0918\u0924\u093e\u0924, \u0924\u094b \u0930\u093e\u091c\u093e \u092c\u094b\u0932\u093e\u0935\u0942\u0902 \u0906\u0932\u093e \u0906\u0939\u0947. \u0930\u093e\u091c\u093e \u0906\u0932\u093e \u0924\u0936\u0940 \u0918\u0930\u0940\u0902 \u091c\u093e\u092f\u0932\u093e \u0928\u093f\u0918\u093e\u0932\u0940. \u090f\u0915\u092e\u0947\u0915\u0940\u0902\u0928\u093e \u092c\u0939\u093f\u0923\u0940\u092c\u0939\u093f\u0923\u0940\u0902\u0928\u0940\u0902 \u0906\u0939\u0947\u0930 \u0915\u0947\u0932\u0947. \u0935\u093e\u091f\u0947\u0928\u0902 \u091c\u093e\u090a \u0932\u093e\u0917\u0932\u0940\u0902. \u092a\u0939\u093f\u0932\u094d\u092f\u093e \u092e\u091c\u0932\u0947\u0938 \u0938\u094d\u0935\u092f\u0902\u092a\u093e\u0915 \u0915\u0947\u0932\u093e. \u0930\u093e\u091c\u093e\u0932\u093e \u0935\u093e\u0922\u0932\u0902, \u092e\u0941\u0932\u093e\u0902\u0928\u093e \u0935\u093e\u0922\u0932\u0902, \u0906\u092a\u0932\u0902 \u092a\u093e\u0928 \u0935\u093e\u0922\u0942\u0928 \u0918\u0947\u0924\u0932\u0902, \u0924\u094b \u0915\u0939\u093e\u0923\u0940\u091a\u0940 \u0906\u0920\u0935\u0923 \u091d\u093e\u0932\u0940. " \u0915\u0930\u093e \u0930\u0947 \u0939\u093e\u0915\u093e\u0930\u093e, \u092a\u093f\u091f\u093e \u0930\u0947 \u0921\u093e\u0902\u0917\u094b\u0930\u093e. \u0928\u0917\u0930\u093e\u0902\u0924 \u0915\u094b\u0923\u0940 \u0909\u092a\u093e\u0936\u0940 \u0906\u0939\u0947 \u0915\u093e? \u092f\u093e\u091a\u093e \u0936\u094b\u0927 \u0915\u0930\u093e." "\u0924\u0941\u091d\u094d\u092f\u093e \u092c\u093e\u0908\u091a\u0940 \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0942\u0928 \u092e\u0932\u093e \u0915\u093e\u092f \u092b\u0933? \u092e\u093e\u091d\u0902 \u092a\u094b\u091f \u092d\u0930\u0932\u0902 \u092a\u093e\u0939\u093f\u091c\u0947." \u0905\u0938\u0902 \u092e\u094d\u0939\u0923\u0942\u0928 \u0924\u094b \u0930\u093e\u0923\u0940\u0915\u0921\u0947 \u0906\u0932\u093e. \u0924\u0936\u0940 \u0938\u0939\u093e \u092e\u094b\u0924\u094d\u092f\u0947 \u0930\u093e\u0923\u0940\u0928\u0902 \u0918\u0947\u090a\u0928 \u0924\u0940\u0928 \u0924\u094d\u092f\u093e\u0932\u093e \u0926\u093f\u0932\u0940\u0902. \u0924\u0940\u0928 \u0906\u092a\u0932\u094d\u092f\u093e \u0939\u093e\u0924\u093e\u0902\u0924 \u0920\u0947\u0935\u0932\u0940\u0902. \u092e\u0928\u094b\u092d\u093e\u0935\u0947\u0902 \u0915\u0939\u093e\u0923\u0940 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0940, \u091a\u093f\u0924\u094d\u0924 \u092d\u093e\u0935\u0947\u0902 \u0924\u094d\u092f\u093e\u0928 \u0910\u0915\u0932\u0940. \u0924\u094d\u092f\u093e\u091a\u0940 \u0932\u093e\u0915\u0921\u093e\u091a\u0940 \u092e\u094b\u0933\u0940 \u0939\u094b\u0924\u0940, \u0924\u0940 \u0938\u094b\u0928\u094d\u092f\u093e\u091a\u0940 \u091d\u093e\u0932\u0940. \u0924\u094b \u092e\u094d\u0939\u0923\u093e\u0932\u093e, "\u092c\u093e\u0908 \u092c\u093e\u0908! \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0932\u094d\u092f\u093e\u091a\u0902 \u090f\u0935\u0922\u0902 \u092b\u0933\u0902, \u092e\u0917 \u0935\u0938\u093e \u0918\u0947\u0924\u0932\u094d\u092f\u093e\u091a\u0902 \u0915\u093e\u092f \u092b\u0933? \u0915\u093e\u092f \u0935\u0938\u093e \u0906\u0939\u0947 \u0924\u094b \u092e\u0932\u093e \u0938\u093e\u0902\u0917\u093e." " \u0924\u0941\u0932\u093e \u0930\u0947 \u0935\u0938\u093e \u0915\u0936\u093e\u0932\u093e \u0939\u0935\u093e? \u0909\u0924\u0936\u0940\u0932, \u092e\u093e\u0924\u0936\u0940\u0932, \u0918\u0947\u0924\u0932\u093e \u0935\u0938\u093e \u091f\u093e\u0915\u0942\u0928 \u0926\u0947\u0936\u0940\u0932," \u0909\u0924\u0924 \u0928\u093e\u0939\u0940, \u092e\u093e\u0924\u0924 \u0928\u093e\u0939\u0940, \u0918\u0947\u0924\u0932\u093e \u0935\u0938\u093e \u091f\u093e\u0915\u0940\u0924 \u0928\u093e\u0939\u0940." \u0924\u0947\u0935\u094d\u0939\u093e\u0902 \u0935\u0938\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u093e.'}),"\n",(0,i.jsx)(a.p,{children:'\u092a\u0941\u0922\u0902 \u0926\u0941\u0938\u0930\u094d\u200d\u092f\u093e \u092e\u091c\u0932\u0947\u0938 \u0917\u0947\u0932\u0940. \u0938\u094d\u0935\u0902\u092f\u092a\u093e\u0915 \u0915\u0947\u0932\u093e. \u0930\u093e\u091c\u093e\u0932\u093e \u0935\u093e\u0922\u0932\u093e, \u092e\u0941\u0932\u093e\u0902\u0928\u093e \u0935\u093e\u0922\u0932\u0902. \u0906\u092a\u0932\u0902 \u092a\u093e\u0928 \u0935\u093e\u0922\u0942\u0928 \u0918\u0947\u0924\u0932\u0902, \u0924\u0947\u0935\u094d\u0939\u093e\u0902 \u0915\u0939\u093e\u0923\u0940\u091a\u0940 \u0906\u0920\u0935\u0923 \u091d\u093e\u0932\u0940. " \u0915\u0930\u093e \u0930\u0947 \u0939\u093e\u0915\u093e\u0930\u093e, \u092a\u093f\u091f\u093e \u0930\u0947 \u0921\u093e\u0902\u0917\u094b\u0930\u093e. \u0928\u0917\u0930\u093e\u0902\u0924 \u0915\u094b\u0923\u0940 \u0909\u092a\u093e\u0936\u0940 \u0906\u0939\u0947 \u0915\u093e? \u092f\u093e\u091a \u0936\u094b\u0927 \u0915\u0930\u093e." "\u0909\u092a\u093e\u0936\u0940 \u0928\u093e\u0939\u0940\u0902, \u0915\u093e\u0939\u0940 \u0928\u093e\u0939\u0940" \u092e\u093e\u0933\u094d\u092f\u093e\u091a\u093e \u092e\u0933\u093e \u092a\u093f\u0915\u0924 \u0928\u093e\u0939\u0940\u0902, \u0935\u093f\u0939\u093f\u0930\u0940\u0932\u093e \u092a\u093e\u0923\u0940 \u0932\u093e\u0917\u0924 \u0928\u093e\u0939\u0940\u0902, \u0905\u0938\u093e \u090f\u0915 \u092e\u093e\u0933\u0940 \u091a\u093f\u0902\u0924\u0947\u0928 \u092c\u0938\u0932\u093e \u0906\u0939\u0947 \u0924\u094d\u092f\u093e\u0932\u093e \u0939\u093e\u0915 \u092e\u093e\u0930\u0932\u0940. \u2018\u0906\u092e\u091a\u094d\u092f\u093e \u092c\u093e\u0908\u091a\u0940 \u0915\u0939\u093e\u0923\u0940 \u0910\u0915." \u0924\u094b \u0906\u0932\u093e. \u0930\u093e\u0923\u0940\u0928\u0902 \u0938\u0939\u093e \u092e\u094b\u0924\u094d\u092f\u0947 \u0918\u0947\u090a\u0928 \u0924\u0940\u0928 \u0906\u092a\u0923 \u0918\u0947\u0924\u0932\u0940\u0902, \u0924\u0940\u0928 \u092e\u093e\u0933\u094d\u092f\u093e\u0932\u093e \u0926\u093f\u0932\u0940\u0902. \u0930\u093e\u0923\u0940\u0928\u0902 \u0915\u0939\u093e\u0923\u0940 \u092e\u0928\u094b\u092d\u093e\u0935\u0947 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0940. \u091a\u093f\u0924\u094d\u0924\u092d\u093e\u0935\u0947 \u092e\u093e\u0933\u094d\u092f\u093e\u0928\u0902 \u0910\u0915\u0932\u0940. \u092e\u093e\u0933\u094d\u092f\u093e\u091a\u093e \u092e\u0933\u093e \u092a\u093f\u0915\u0942\u0902 \u0932\u093e\u0917\u0932\u093e. \u0935\u093f\u0939\u093f\u0930\u0940\u0932\u093e \u092a\u093e\u0923\u0940 \u0906\u0932\u0902. \u0924\u094b \u092e\u094d\u0939\u0923\u093e\u0932\u093e, " \u092c\u093e\u0908 \u092c\u093e\u0908! \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0932\u094d\u092f\u093e\u0935\u0930 \u090f\u0935\u0922\u0902 \u092b\u0933, \u092e\u0917 \u0935\u0938\u093e \u0918\u0947\u0924\u0932\u094d\u092f\u093e\u091a\u0902 \u0915\u093e\u092f \u092b\u0933? \u0915\u093e\u092f \u0935\u0938\u093e \u0905\u0938\u0947\u0932 \u0924\u094b \u092e\u0932\u093e \u0938\u093e\u0902\u0917\u093e." \u092e\u0917 \u0930\u093e\u0923\u0940\u0928\u0902 \u0924\u094d\u092f\u093e\u0932\u093e \u0935\u0938\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u093e.'}),"\n",(0,i.jsx)(a.p,{children:'\u092a\u0941\u0922\u0902 \u0924\u093f\u0938\u0930\u094d\u200d\u092f\u093e \u092e\u091c\u0932\u0947\u0938 \u0917\u0947\u0932\u0940 \u0938\u094d\u0935\u0902\u092f\u092a\u093e\u0915 \u0915\u0947\u0932\u093e. \u0930\u093e\u091c\u093e\u0932\u093e \u0935\u093e\u0922\u0932\u0902. \u092e\u0941\u0932\u093e\u0902\u0928\u093e \u0935\u093e\u0922\u0932\u0902. \u0906\u092a\u0932\u0902 \u092a\u093e\u0928 \u0935\u093e\u0922\u0942\u0928 \u0918\u0947\u0924\u0932\u0902, \u0924\u0947\u0935\u094d\u0939\u093e \u0915\u0939\u093e\u0923\u0940\u091a\u0940 \u0906\u0920\u0935\u0923 \u091d\u093e\u0932\u0940. " \u0915\u0930\u093e \u0930\u0947 \u0939\u093e\u0902\u0915\u093e\u0930\u093e, \u092a\u093f\u091f\u093e \u0930\u0947 \u0921\u093e\u0902\u0917\u094b\u0930\u093e. \u0928\u0917\u0930\u093e\u0902\u0924 \u0915\u094b\u0923\u0940 \u0909\u092a\u093e\u0936\u0940 \u0906\u0939\u0947 \u0915\u093e? \u092f\u093e\u091a\u093e \u0936\u094b\u0927 \u0915\u0930\u093e." "\u0909\u092a\u093e\u0936\u0940 \u0928\u093e\u0939\u0940\u0902, \u0915\u093e\u0939\u0940 \u0928\u093e\u0939\u0940\u0902." \u090f\u0915 \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940, \u0924\u093f\u091a\u093e \u090f\u0915 \u092e\u0941\u0932\u0917\u093e \u0935\u0928\u093e\u0902\u0924 \u0917\u0947\u0932\u093e \u0939\u094b\u0924\u093e, \u090f\u0915 \u0921\u094b\u0939\u093e\u0902\u0924 \u092c\u0941\u0921\u093e\u0932\u093e \u0939\u094b\u0924\u093e, \u090f\u0915 \u0938\u0930\u094d\u092a\u093e\u0928\u0902 \u0916\u093e\u0932\u094d\u0932\u093e \u0939\u094b\u0924\u093e, \u0924\u094d\u092f\u093e\u092e\u0941\u0933\u0902 \u091a\u093f\u0902\u0924\u093e\u0915\u094d\u0930\u093e\u0902\u0924 \u092c\u0938\u0932\u0940 \u0939\u094b\u0924\u0940. \u0924\u093f\u0932\u093e \u092e\u094d\u0939\u0923\u093e\u0932\u0947, " \u0906\u092e\u091a\u094d\u092f\u093e \u092c\u093e\u0908\u091a\u0940 \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0942." \u0924\u0940 \u092e\u094d\u0939\u0923\u093e\u0932\u0940, " \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0942\u0928 \u092e\u0940 \u0915\u093e\u092f \u0915\u0930\u0942\u0902? \u092e\u0940 \u092e\u0941\u0932\u093e\u0902\u0938\u093e\u0920\u0940 \u0930\u0921\u0924\u0947 \u0906\u0939\u0947\u0902. \u092c\u0930\u0902 \u092f\u0947\u0924\u0947" \u092e\u0917 \u0924\u0940 \u0930\u093e\u0923\u0940\u0915\u0921\u0947 \u0906\u0932\u0940. \u0930\u093e\u0923\u0940\u0928\u0902 \u092a\u0939\u093f\u0932\u094d\u092f\u093e\u092a\u094d\u0930\u092e\u093e\u0923\u0902 \u0924\u093f\u0932\u093e \u0915\u0939\u093e\u0923\u0940 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0940. \u0924\u093f\u0928\u0902 \u091a\u093f\u0924\u094d\u0924\u092d\u093e\u0935\u0947 \u0910\u0915\u0932\u0940. \u0924\u093f\u091a\u093e \u092e\u0941\u0932\u0917\u093e \u0935\u0928\u093e\u0902\u0924 \u0917\u0947\u0932\u093e \u0939\u094b\u0924\u093e \u0924\u094b \u0906\u0932\u093e. \u0921\u094b\u0939\u093e\u0902\u0924 \u092c\u0941\u0921\u093e\u0932\u093e \u0939\u094b\u0924\u093e \u0924\u094b \u0906\u0932\u093e. \u0938\u0930\u094d\u092a\u093e\u0928\u0902 \u0916\u093e\u0932\u094d\u0932\u093e \u0939\u094b\u0924\u093e \u0924\u094b \u0906\u0932\u093e. \u0924\u0940 \u092e\u094d\u0939\u0923\u093e\u0932\u0940," \u092c\u093e\u0908 \u092c\u093e\u0908! \u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0932\u094d\u092f\u093e\u091a\u0902 \u0939\u0947\u0902 \u092b\u0933, \u092e\u0917 \u0935\u0938\u093e \u0918\u0947\u0924\u0932\u094d\u092f\u093e\u091a\u0902 \u0915\u093e\u092f \u092b\u0933? \u0915\u093e\u092f \u0935\u0938\u093e \u0924\u094b \u092e\u0932\u093e \u0938\u093e\u0902\u0917\u093e." \u092e\u0917 \u0930\u093e\u0923\u0940\u0928\u0902 \u0924\u093f\u0932\u093e\u0939\u0940 \u0935\u0938\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u093e.'}),"\n",(0,i.jsx)(a.p,{children:'\u092a\u0941\u0922\u0902 \u091a\u094c\u0925\u094d\u092f\u093e \u092e\u091c\u0932\u0947\u0938 \u0917\u0947\u0932\u0940\u0902. \u0938\u094d\u0935\u0902\u092f\u092a\u093e\u0915 \u0915\u0947\u0932\u093e. \u0930\u093e\u091c\u093e\u0932\u093e \u0935\u093e\u0922\u0932\u0902, \u092e\u0941\u0932\u093e\u0902\u0928\u093e \u0935\u093e\u0922\u0932\u0902. \u0906\u092a\u0932\u0902 \u092a\u093e\u0928 \u0935\u093e\u0922\u0942\u0928 \u0918\u0947\u0924\u0932\u0902, \u0924\u0947\u0935\u094d\u0939\u093e\u0902 \u0915\u0939\u093e\u0923\u0940\u091a\u0940 \u0906\u0920\u0935\u0923 \u091d\u093e\u0932\u0940. "\u0915\u0930\u093e \u0930\u0947 \u0939\u093e\u0902\u0915\u093e\u0930\u093e, \u092a\u093f\u091f\u093e \u0930\u0947 \u0921\u093e\u0902\u0917\u094b\u0930\u093e. \u0928\u0917\u0930\u093e\u0902\u0924 \u0915\u094b\u0923\u0940 \u0909\u092a\u093e\u0936\u0940 \u0906\u0939\u0947 \u0915\u093e? \u092f\u093e\u091a\u093e \u0936\u094b\u0927 \u0915\u0930\u093e." "\u0909\u092a\u093e\u0936\u0940 \u0928\u093e\u0939\u0940\u0902, \u0915\u093e\u0939\u0940 \u0928\u093e\u0939\u0940\u0902." \u0915\u093e\u0923\u093e \u0921\u094b\u0933\u093e, \u092e\u093e\u0902\u0938\u093e\u091a\u093e \u0917\u094b\u0933\u093e, \u0939\u093e\u0924 \u0928\u093e\u0939\u0940\u0902, \u092a\u093e\u092f \u0928\u093e\u0939\u0940\u0902, \u0905\u0938\u093e \u090f\u0915 \u092e\u0928\u0941\u0937\u094d\u092f \u0930\u0938\u094d\u0924\u094d\u092f\u093e\u092e\u0927\u094d\u092f\u0947\u0902 \u0939\u094b\u0924\u093e. \u0924\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u0905\u0902\u0917\u093e\u0935\u0930 \u0924\u093e\u0902\u092c\u094d\u092f\u093e\u092d\u0930 \u092a\u093e\u0923\u0940 \u0913\u0924\u0932\u0902 \u092a\u093e\u0932\u0925\u093e \u0939\u094b\u0924\u093e \u0924\u094b \u0909\u0924\u093e\u0923\u093e \u0915\u0947\u0932\u093e. \u0938\u0939\u093e \u092e\u094b\u0924\u094d\u092f\u0947 \u0939\u094b\u0924\u0940\u0902. \u0924\u0940\u0928 \u092e\u094b\u0924\u094d\u092f\u0947 \u0924\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092c\u0947\u0902\u092c\u0940\u0935\u0930 \u0920\u0947\u0935\u0932\u0940\u0902, \u0924\u0940\u0928 \u092e\u094b\u0924\u094d\u092f\u0947 \u0906\u092a\u0923 \u0918\u0947\u0924\u0932\u0940\u0902, \u0930\u093e\u0923\u0940\u0928\u0902 \u092e\u0928\u094b\u092d\u093e\u0935\u0947 \u0915\u0939\u093e\u0923\u0940 \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u0940; \u0924\u0940 \u0924\u094d\u092f\u093e\u0928\u0902 \u0910\u0915\u0932\u0940. \u0924\u094d\u092f\u093e\u0932\u093e \u0939\u093e\u0924\u092a\u093e\u092f \u0906\u0932\u0947. \u0926\u0947\u0939 \u0926\u093f\u0935\u094d\u092f \u091d\u093e\u0932\u093e. \u0924\u094b \u092e\u094d\u0939\u0923\u093e\u0932\u093e, "\u0915\u0939\u093e\u0923\u0940 \u0910\u0915\u0932\u094d\u092f\u093e\u091a\u0902 \u090f\u0935\u0922\u0902 \u092b\u0933, \u092e\u0917 \u0935\u0938\u093e \u0918\u0947\u0924\u0932\u094d\u092f\u093e\u091a\u0902 \u0915\u093e\u092f \u092b\u0933? \u0915\u093e\u092f \u0935\u0938\u093e \u0924\u094b \u092e\u0932\u093e \u0938\u093e\u0902\u0917\u093e. \u092e\u0917 \u0930\u093e\u0923\u0940\u0928\u0902 \u0924\u094d\u092f\u093e\u0932\u093e \u0935\u0938\u093e \u0938\u093e\u0902\u0917\u093f\u0924\u0932\u093e.'}),"\n",(0,i.jsx)(a.p,{children:'\u092a\u093e\u0902\u091a\u0935\u094d\u092f\u093e \u092e\u0941\u0915\u094d\u0915\u093e\u092e\u093e\u0932\u093e \u0918\u0930\u0940 \u0906\u0932\u0940\u0902. \u0938\u094d\u0935\u0902\u092f\u092a\u093e\u0915 \u0915\u0947\u0932\u093e. \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923 \u091c\u0947\u0935\u093e\u092f\u0932\u093e \u0906\u0932\u0947. \u0938\u093e\u0924\u0940 \u0926\u0930\u0935\u093e\u091c\u0947 \u0909\u0918\u0921\u0932\u0947. \u0932\u094b\u0939\u0918\u0902\u0917\u093e\u0933\u0902 \u092a\u093e\u0923\u0940 \u0924\u093e\u092a\u0935\u0932\u0902. \u092a\u0921\u094d\u0930\u0938 \u092a\u0915\u094d\u0915\u093e\u0928\u094d\u0928\u0902 \u091c\u0947\u0935\u093e\u092f\u0932\u093e \u0915\u0947\u0932\u0940\u0902. \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923 \u092d\u094b\u091c\u0928\u093e\u0932\u093e \u092c\u0938\u0932\u0947, \u0924\u094d\u092f\u093e\u0902\u0928\u093e \u092a\u0939\u093f\u0932\u094d\u092f\u093e \u0918\u093e\u0938\u093e\u0932\u093e \u0915\u0947\u0938 \u0932\u093e\u0917\u0932\u093e. \u0924\u0947 \u092e\u094d\u0939\u0923\u093e\u0932\u0947, "\u0905\u0917 \u0905\u0917, \u0915\u094b\u0923\u093e\u091a\u094d\u092f\u093e \u092a\u093e\u092a\u0923\u0940\u091a\u093e \u0915\u0947\u0938 \u0906\u0939\u0947?" \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0932\u093e \u092c\u093e\u0930\u093e \u0935\u0930\u094d\u0937\u0902 \u0926\u0930\u093f\u0926\u094d\u0930 \u0906\u0932\u0902 \u0939\u094b\u0924\u0902. \u0924\u093f\u0928\u0902 \u0906\u0926\u093f\u0924\u0935\u093e\u0930\u0940\u0902 \u0935\u0933\u091a\u0923\u0940\u0916\u093e\u0932\u0940\u0902 \u092c\u0938\u0942\u0928 \u0915\u0947\u0938 \u0935\u093f\u0902\u091a\u0930\u0932\u0947. "\u0915\u093e\u0933\u0902 \u091a\u0935\u093e\u0933\u0902, \u0921\u094b\u0908\u091a\u093e \u0915\u0947\u0902\u0938, \u0935\u0933\u091a\u0923\u0940\u091a\u0940 \u0915\u093e\u0921\u0940, \u0921\u093e\u0935\u094d\u092f\u093e \u0916\u093e\u0902\u0926\u094d\u092f\u093e\u0935\u0930\u0942\u0928 \u0935\u0947\u0936\u0940\u092c\u093e\u0939\u0947\u0930 \u091f\u093e\u0915\u0942\u0928 \u0926\u0947." \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0932\u093e \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923\u093e\u091a\u093e \u0915\u094b\u092a \u091d\u093e\u0932\u093e, \u0924\u0938\u093e \u0915\u094b\u0923\u093e\u0932\u093e \u0939\u094b\u090a \u0928\u092f\u0947.'}),"\n",(0,i.jsx)(a.p,{children:"\u092c\u094d\u0930\u093e\u0939\u094d\u092e\u0923\u093e\u0932\u093e, \u092e\u094b\u0933\u0940\u0935\u093f\u0915\u094d\u092f\u093e\u0932\u093e, \u0930\u093e\u091c\u093e\u091a\u094d\u092f\u093e \u0930\u093e\u0923\u0940\u0932\u093e, \u092e\u093e\u0933\u094d\u092f\u093e\u0932\u093e, \u092e\u094d\u0939\u093e\u0924\u093e\u0930\u0940\u0932\u093e, \u0915\u094b\u0923\u093e \u0921\u094b\u0933\u093e \u092e\u093e\u0902\u0938\u093e\u091a\u093e \u0917\u094b\u0933\u093e, \u0907\u0924\u0915\u094d\u092f\u093e\u0902\u0928\u093e \u091c\u0938\u093e \u0938\u0942\u0930\u094d\u092f\u0928\u093e\u0930\u093e\u092f\u0923 \u092a\u094d\u0930\u0938\u0928\u094d\u0928 \u091d\u093e\u0932\u093e, \u0924\u0938\u093e \u0924\u0941\u092e\u094d\u0939\u093e \u0906\u092e\u094d\u0939\u093e \u0939\u094b\u0935\u094b\u0902. \u0939\u0940 \u0938\u093e\u0920\u093e\u0902 \u0909\u0924\u094d\u0924\u0930\u093e\u091a\u0940 \u0915\u0939\u093e\u0923\u0940, \u092a\u093e\u0902\u091a\u093e \u0909\u0924\u094d\u0924\u0930\u0940 \u0938\u0941\u092b\u0933 \u0938\u0902\u092a\u0942\u0930\u094d\u0923. \u200b"}),"\n",(0,i.jsx)("span",{class:"index-text",children:" aditya ranubai paush ravivar devanchi kahani katha"})]})}function l(n={}){const{wrapper:a}={...(0,r.R)(),...n.components};return a?(0,i.jsx)(a,{...n,children:(0,i.jsx)(o,{...n})}):o(n)}},28453(n,a,e){e.d(a,{R:()=>s,x:()=>c});var t=e(96540);const i={},r=t.createContext(i);function s(n){const a=t.useContext(r);return t.useMemo(function(){return"function"==typeof n?n(a):{...a,...n}},[a,n])}function c(n){let a;return a=n.disableParentContext?"function"==typeof n.components?n.components(i):n.components||i:s(n.components),t.createElement(r.Provider,{value:a},n.children)}}}]);